INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2017, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2017): O ano de 1881 foi dos mais significativos e importantes para a ficção no Brasil, pois que nele se publicaram as Memórias Póstumas de Brás Cubas, de Machado de Assis (saídas na Revista Brasileira, no ano anterior) e O Mulato, de Aluísio Azevedo. Com estes livros se encerrava a indecisão da década de setenta, e tomavam corpo duas das tendências nela delineadas, a da análise, prenunciada nos primeiro | Embora seja um objeto importante nos dois romances mencionados — O Mulato e Memórias Póstumas de Brás Cubas —, o “sinete” (R.82) mostra-se fundamental no romance de Aluísio Azevedo, de feição naturalista. 2 Segundo a autora do texto, o elemento de escândalo social intrínseco à temática de Memórias Póstumas de Brás Cubas não foi compreendido pelo meio intelectual, nem pelo público, no momento da publicação do romance na Revista Brasileira, em 1880, tampouco em seu lançamento em formato de livro, em 1881. 3 A autora argumenta, no texto, que o romance de Machado de Assis é r', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2017): O ano de 1881 foi dos mais significativos e importantes para a ficção no Brasil, pois que nele se publicaram as Memórias Póstumas de Brás Cubas, de Machado de Assis (saídas na Revista Brasileira, no ano anterior) e O Mulato, de Aluísio Azevedo. Com estes livros se encerrava a indecisão da década de setenta, e tomavam corpo duas das tendências nela delineadas, a da análise, prenunciada nos primeiro | O narrador supõe existir um “verdadeiro Leiva” (R.64), que se vislumbra na “poesia palaciana e de modista” (R.59) deste personagem, e imagina que, caso passasse a viver em condições econômicas mais favoráveis, Leiva se revelaria descrente dos ideais revolucionários e atraído pelo conforto material.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2017, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2017): O ano de 1881 foi dos mais significativos e importantes para a ficção no Brasil, pois que nele se publicaram as Memórias Póstumas de Brás Cubas, de Machado de Assis (saídas na Revista Brasileira, no ano anterior) e O Mulato, de Aluísio Azevedo. Com estes livros se encerrava a indecisão da década de setenta, e tomavam corpo duas das tendências nela delineadas, a da análise, prenunciada nos primeiro | O narrador discorda da opinião geral dos amigos de Leiva, que o julgam “perfeitamente hipócrita” (R.60), e considera que tal julgamento advém do meio pobre e humilde que Leiva frequenta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2017, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2017): O ano de 1881 foi dos mais significativos e importantes para a ficção no Brasil, pois que nele se publicaram as Memórias Póstumas de Brás Cubas, de Machado de Assis (saídas na Revista Brasileira, no ano anterior) e O Mulato, de Aluísio Azevedo. Com estes livros se encerrava a indecisão da década de setenta, e tomavam corpo duas das tendências nela delineadas, a da análise, prenunciada nos primeiro | Nos trechos “Eu gostava de notar a adoração pela violência que as suas almas pacíficas tinham” (R. 34 e 35) e “Era um grupo de protestantes, detestando a política” (R. 48 e 49), o narrador alude a uma ambivalência no comportamento de Leiva e de seus amigos. CESPE | CEBRASPE – IRBr – Aplicação: 2017 QUESTÃO 4 Considerando as relações semântico-sintáticas estabelecidas no texto II, julgue (C ou E) os itens a seguir. Texto III 1 Escrita em prosa e verso, a Carta Marítima é formalmente um poema sui generis, que supera as divisões convencionais do discurso. Quanto à mensagem, ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
